/* From Uiverse.io by NouvelleTechno - Tags: card */
.__UIV_SCOPE__ .card {
  width: 350px;
  background: white;
  padding: 20px;
  position: relative;
}

.__UIV_SCOPE__ .card .title {
  color: black;
  font-size: 2rem;
  font-weight: 600;
}

.__UIV_SCOPE__ .card .description {
  color: black;
  margin-top: 10px;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .card .prefs {
  color: blue;
}

.__UIV_SCOPE__ .card .actions {
  margin-top: 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: .8em;
}

.__UIV_SCOPE__ .card button {
  border: 1px solid;
  border-radius: 4px;
  padding: 5px;
  background: none;
  font-size: 1.2em;
  font-weight: bold;
}

.__UIV_SCOPE__ .card .decline {
  border-color: red;
  color: red;
}

.__UIV_SCOPE__ .card .decline:hover {
  background-color: red;
  color: white;
}

.__UIV_SCOPE__ .card .valid {
  border-color: green;
  color: green;
}

.__UIV_SCOPE__ .card .valid:hover {
  background-color: green;
  color: white;
}

.__UIV_SCOPE__ .card div::before, .__UIV_SCOPE__ div::after {
  content: "";
  z-index: -1;
  position: absolute;
  bottom: 15px;
  left: 10px;
  width: 50%;
  top: 80%;
  max-width: 300px;
  background: rgba(0,0,0,0.7);
  -webkit-box-shadow: 0 15px 10px rgba(0,0,0,0.7);
  box-shadow: 0 15px 10px rgba(0,0,0,0.7);
  -webkit-transform: rotate(-3deg);
  transform: rotate(-3deg);
}

.__UIV_SCOPE__ .card div::after {
  right: 10px;
  left: unset;
  transform: rotate(3deg);
}
